<div id="kt_content_container" class="container-xxl py-5"><div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Control de Stock</h1><div class="text-muted fs-6">Consulta las existencias actuales de tus productos</div></div></div><div class="card card-flush"><div class="card-body pt-0"><table class="table align-middle table-row-dashed fs-6 gy-5" id="tabla_stock"><thead><tr class="text-start text-gray-500 fw-bold fs-7 text-uppercase gs-0"><th>Producto</th><th>Categoría</th><th>Stock</th><th>Precio</th><th>Estado</th></tr></thead><tbody></tbody></table></div></div></div>
<script>(function(){fetch('actions/12.read_productos.php').then(r=>r.json()).then(res=>{if(!res.success)return;$('#tabla_stock').DataTable({data:(res.data||[]).map(p=>['<span class="fw-bold">'+p.nombre+'</span>',p.categoria_nombre||'Sin categoría',p.stock,'$'+Number(p.precio).toFixed(2),Number(p.stock)<=0?'<span class="badge badge-light-danger">Agotado</span>':Number(p.stock)<=10?'<span class="badge badge-light-warning">Stock bajo</span>':'<span class="badge badge-light-success">Disponible</span>']),columns:[{title:'Producto'},{title:'Categoría'},{title:'Stock'},{title:'Precio'},{title:'Estado'}],pageLength:10,language:{url:'https://cdn.datatables.net/plug-ins/1.13.7/i18n/es-ES.json'}});});})();</script>
